<?php
if ( php_sapi_name() !== 'cli' ) { exit; } // solo terminal, nunca via web
/**
 * HOMVUK Autos PRO v2 (hvkp-autos2)
 *
 * Sobre lo ya instalado, agrega SIN archivos PHP persistentes:
 *  1. Documentos obligatorios en el formulario del vehiculo: ID + licencia
 *     (validados en servidor, guardados en el pedido para el dueno).
 *  2. Deposito de garantia USD $300 (reembolsable) cobrado junto a la reserva.
 *  3. Pagina de Terminos y Condiciones + casilla de aceptacion obligatoria
 *     en el checkout (nativa de WooCommerce).
 *  4. Descripcion correcta del Porsche Cayenne 2018 (tenia la del MG3).
 *
 * Uso:  php hvkp-autos2.php            (instalar)
 *       php hvkp-autos2.php restore    (revertir esta fase)
 */

$HVKA_SNIPPET_B64 = '';
$HVKA_SNIPPET_MD5 = '38d22bd2fee697eb42aa836424c1d4d9';
$HVKA_TERMS_B64   = '';
$HVKA_PORSCHE_B64 = '';
$HVKA_NAME        = 'HOMVUK Autos PRO';

require __DIR__ . '/wp-load.php';
global $wpdb;

$mode  = isset( $argv[1] ) ? $argv[1] : 'install';
$ok    = array();
$warn  = array();
$table = $wpdb->prefix . 'snippets';

$purge_caches = function () {
    if ( class_exists( '\Elementor\Plugin' ) ) {
        try { \Elementor\Plugin::instance()->files_manager->clear_cache(); } catch ( \Throwable $e ) {}
    }
    if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
    do_action( 'litespeed_purge_all' );
    if ( function_exists( 'rocket_clean_domain' ) ) { rocket_clean_domain(); }
    if ( function_exists( 'w3tc_flush_all' ) ) { w3tc_flush_all(); }
    if ( function_exists( 'wp_cache_clear_cache' ) ) { wp_cache_clear_cache(); }
};

if ( 'restore' === $mode ) {
    $b = get_option( 'hvkp_autos2_backup' );
    if ( ! is_array( $b ) ) {
        echo "[AVISO] No hay respaldo de esta fase; nada que restaurar.\n";
        exit( 0 );
    }
    if ( isset( $b['snippet_code'] ) && '' !== $b['snippet_code'] ) {
        $wpdb->update( $table, array( 'code' => $b['snippet_code'], 'scope' => $b['snippet_scope'] ), array( 'name' => $HVKA_NAME ) );
        echo "[OK]    Snippet restaurado a la version anterior\n";
    }
    if ( isset( $b['porsche_id'], $b['porsche_content'] ) && $b['porsche_id'] ) {
        wp_update_post( array( 'ID' => (int) $b['porsche_id'], 'post_content' => $b['porsche_content'] ) );
        echo "[OK]    Descripcion anterior del Porsche restaurada\n";
    }
    if ( isset( $b['terms_opt'] ) ) {
        update_option( 'woocommerce_terms_page_id', $b['terms_opt'] );
        echo "[OK]    Opcion de pagina de terminos restaurada\n";
    }
    if ( ! empty( $b['terms_page_created'] ) ) {
        wp_trash_post( (int) $b['terms_page_created'] );
        echo "[OK]    Pagina de terminos enviada a papelera\n";
    }
    $purge_caches();
    echo "Restauracion completa.\n";
    exit( 0 );
}

$backup = array();

// 1) Actualizar snippet a v2 (md5 verificado) y pasarlo a ambito global
$code = base64_decode( $HVKA_SNIPPET_B64 );
if ( md5( $code ) !== $HVKA_SNIPPET_MD5 ) {
    echo "[ERROR] El snippet embebido no paso la verificacion md5. Nada fue modificado.\n";
    exit( 1 );
}
$prev = $wpdb->get_row( $wpdb->prepare( "SELECT id, code, scope FROM $table WHERE name = %s", $HVKA_NAME ) );
if ( ! $prev ) {
    echo "[ERROR] No existe el snippet 'HOMVUK Autos PRO' (corre primero hvkp-autos.php).\n";
    exit( 1 );
}
$backup['snippet_code']  = $prev->code;
$backup['snippet_scope'] = $prev->scope;
$wpdb->update(
    $table,
    array( 'code' => $code, 'scope' => 'global', 'active' => 1, 'modified' => current_time( 'mysql' ) ),
    array( 'id' => (int) $prev->id )
);
$ok[] = 'Snippet actualizado a v2: documentos obligatorios + deposito USD $300 (id ' . $prev->id . ')';

// 2) Carpeta protegida para los documentos de los clientes
$updir = wp_upload_dir();
$docs  = trailingslashit( $updir['basedir'] ) . 'homvuk-docs';
if ( ! is_dir( $docs ) ) {
    wp_mkdir_p( $docs );
}
if ( ! file_exists( $docs . '/index.html' ) ) {
    file_put_contents( $docs . '/index.html', '' );
}
$ok[] = 'Carpeta de documentos lista (uploads/homvuk-docs, nombres aleatorios, sin listado)';

// 3) Pagina de Terminos y Condiciones + casilla obligatoria en el checkout
$backup['terms_opt'] = get_option( 'woocommerce_terms_page_id', '' );
$terms_html = base64_decode( $HVKA_TERMS_B64 );
$existing_terms = get_page_by_path( 'terminos-y-condiciones-de-arriendo', OBJECT, 'page' );
if ( $existing_terms && 'trash' !== $existing_terms->post_status ) {
    $terms_id = $existing_terms->ID;
    wp_update_post( array( 'ID' => $terms_id, 'post_content' => $terms_html, 'post_status' => 'publish' ) );
    $ok[] = 'Pagina de terminos actualizada (id ' . $terms_id . ')';
} else {
    $terms_id = wp_insert_post( array(
        'post_title'   => 'Términos y Condiciones de Arriendo',
        'post_name'    => 'terminos-y-condiciones-de-arriendo',
        'post_content' => $terms_html,
        'post_status'  => 'publish',
        'post_type'    => 'page',
    ) );
    $backup['terms_page_created'] = $terms_id;
    $ok[] = 'Pagina de terminos creada (id ' . $terms_id . ')';
}
if ( $terms_id && ! is_wp_error( $terms_id ) ) {
    update_option( 'woocommerce_terms_page_id', (int) $terms_id );
    $ok[] = 'Casilla "Acepto los terminos y condiciones" activada como obligatoria en el checkout';
}

// 4) Descripcion correcta del Porsche Cayenne 2018
$porsche = get_page_by_path( 'porsche-cayenne-2018', OBJECT, 'product' );
if ( $porsche ) {
    $backup['porsche_id']      = $porsche->ID;
    $backup['porsche_content'] = $porsche->post_content;
    wp_update_post( array( 'ID' => $porsche->ID, 'post_content' => base64_decode( $HVKA_PORSCHE_B64 ) ) );
    $ok[] = 'Descripcion del Porsche Cayenne 2018 corregida (tenia la ficha del MG3)';
} else {
    $warn[] = 'No se encontro el producto porsche-cayenne-2018; descripcion no tocada';
}

update_option( 'hvkp_autos2_backup', $backup, false );

// 5) Purga de caches y verificacion en vivo
$purge_caches();
$purl = $porsche ? get_permalink( $porsche->ID ) : home_url( '/experiencia/porsche-cayenne-2018/' );
$resp = wp_remote_get( add_query_arg( 'hvka2', time(), $purl ), array( 'timeout' => 30, 'sslverify' => false ) );
if ( is_wp_error( $resp ) ) {
    $warn[] = 'No se pudo verificar en vivo: ' . $resp->get_error_message();
} else {
    $body = (string) wp_remote_retrieve_body( $resp );
    if ( false !== strpos( $body, 'hvka_doc_id' ) ) {
        $ok[] = 'Verificado: campos de documento y licencia presentes en la pagina del auto';
    } else {
        $warn[] = 'Los campos de documentos aun no aparecen (puede ser cache; revisar en unos minutos)';
    }
    if ( false !== strpos( $body, 'dep' . 'osito de garant' ) || false !== strpos( $body, 'sito de garant' ) ) {
        $ok[] = 'Verificado: aviso del deposito de garantia visible';
    }
    if ( false === strpos( $body, 'El MG3' ) ) {
        $ok[] = 'Verificado: la descripcion del Porsche ya no muestra la ficha del MG3';
    } else {
        $warn[] = 'La pagina del Porsche aun muestra texto del MG3 (puede ser cache)';
    }
}
$tresp = wp_remote_get( get_permalink( (int) $terms_id ), array( 'timeout' => 30, 'sslverify' => false ) );
if ( ! is_wp_error( $tresp ) && 200 === (int) wp_remote_retrieve_response_code( $tresp ) ) {
    $ok[] = 'Verificado: pagina de terminos publicada -> ' . get_permalink( (int) $terms_id );
} else {
    $warn[] = 'No se pudo verificar la pagina de terminos (revisar permalinks)';
}

echo "== HOMVUK Autos PRO v2 (sin archivos PHP persistentes) ==\n";
foreach ( $ok as $m )   { echo "[OK]    $m\n"; }
foreach ( $warn as $m ) { echo "[AVISO] $m\n"; }
echo "Listo. Este instalador puede borrarse: rm -f hvkp-autos2.php\n";
echo "Para revertir esta fase: php hvkp-autos2.php restore\n";
